CREATE TABLE Z_PRIMARYKEY (Z_ENT INTEGER PRIMARY KEY, Z_NAME VARCHAR, Z_SUPER INTEGER, Z_MAX INTEGER);
CREATE TABLE ZITEM ( Z_PK INTEGER PRIMARY KEY, Z_ENT INTEGER, Z_OPT INTEGER, ZBPM INTEGER, ZFADEOUT INTEGER, ZKEY INTEGER, ZMINUTES INTEGER, ZPLACEHOLDER INTEGER, ZSECONDS INTEGER, ZSELECTEDTRACK INTEGER, ZSIGNATUREBOTTOM INTEGER, ZSIGNATURETOP INTEGER, ZVERSION INTEGER, ZDIFFICULTY INTEGER, ZRATING INTEGER, ZENDPAGE INTEGER, ZINDENT INTEGER, ZSTARTPAGE INTEGER, ZSCORE INTEGER, ZDISPLAYZOOM INTEGER, ZPRINTNUMBER INTEGER, ZLASTPLAYED TIMESTAMP, ZADDED TIMESTAMP, ZMODIFIED TIMESTAMP, ZZOOM FLOAT, ZPATH VARCHAR, ZPITCH VARCHAR, ZREFERENCE VARCHAR, ZSHORTCUT VARCHAR, ZSORTTITLE VARCHAR, ZTITLE VARCHAR, ZUUID VARCHAR, ZSIZE VARCHAR, ZMIDI BLOB, ZUNKNOWNFIELDS BLOB, ZVERSIONS BLOB, ZTOC BLOB, ZUNKNOWNFIELDS1 BLOB );
